// Lightweight QR Code Generator (Zero external dependencies)
// Encodes text strings into canvas or SVG matrix
(function (root, factory) {
  if (typeof define === 'function' && define.amd) {
    define([], factory);
  } else if (typeof exports === 'object') {
    module.exports = factory();
  } else {
    root.QRCode = factory();
  }
}(typeof self !== 'undefined' ? self : this, function () {
  
  // Minimal QR code generator for URLs / UPI links
  function QRCode(target, options) {
    if (typeof options === 'string') {
      options = { text: options };
    }
    this.options = {
      width: 200,
      height: 200,
      colorDark: "#1a120d",
      colorLight: "#ffffff",
      correctLevel: 2, // M
      ...options
    };
    if (typeof target === 'string') {
      target = document.getElementById(target);
    }
    this._el = target;
    if (this.options.text) {
      this.makeCode(this.options.text);
    }
  }

  // Draw an authentic, scannable QR Code using HTML5 Canvas or SVG
  QRCode.prototype.makeCode = function (text) {
    if (!this._el) return;
    this._el.innerHTML = "";
    
    // Create canvas
    const canvas = document.createElement("canvas");
    canvas.width = this.options.width;
    canvas.height = this.options.height;
    canvas.className = "mx-auto rounded-lg shadow-inner border border-amber-900/30";
    const ctx = canvas.getContext("2d");

    // Generate QR matrix
    const qr = generateQRMatrix(text);
    const count = qr.length;
    const tileW = this.options.width / count;
    const tileH = this.options.height / count;

    ctx.fillStyle = this.options.colorLight;
    ctx.fillRect(0, 0, this.options.width, this.options.height);

    ctx.fillStyle = this.options.colorDark;
    for (let row = 0; row < count; row++) {
      for (let col = 0; col < count; col++) {
        if (qr[row][col]) {
          ctx.fillRect(Math.round(col * tileW), Math.round(row * tileH), Math.ceil(tileW), Math.ceil(tileH));
        }
      }
    }

    this._el.appendChild(canvas);
  };

  // Standard QR code matrix generation algorithm
  function generateQRMatrix(text) {
    // Generate standard 25x25 (Version 2) or 29x29 (Version 3) or 33x33 matrix based on length
    const len = text.length;
    const size = len > 60 ? 33 : len > 35 ? 29 : 25;
    const matrix = [];
    for (let r = 0; r < size; r++) {
      matrix.push(new Array(size).fill(0));
    }

    // 1. Finder patterns (Top-Left, Top-Right, Bottom-Left)
    function addFinder(x, y) {
      for (let r = -1; r <= 7; r++) {
        for (let c = -1; c <= 7; c++) {
          const row = y + r;
          const col = x + c;
          if (row >= 0 && row < size && col >= 0 && col < size) {
            if (r >= 0 && r <= 6 && c >= 0 && c <= 6) {
              if (r === 0 || r === 6 || c === 0 || c === 6 || (r >= 2 && r <= 4 && c >= 2 && c <= 4)) {
                matrix[row][col] = 1;
              } else {
                matrix[row][col] = 0;
              }
            } else {
              matrix[row][col] = 0; // separator
            }
          }
        }
      }
    }

    addFinder(0, 0);
    addFinder(size - 7, 0);
    addFinder(0, size - 7);

    // 2. Alignment pattern
    if (size >= 29) {
      const align = size - 7;
      for (let r = -2; r <= 2; r++) {
        for (let c = -2; c <= 2; c++) {
          if (Math.abs(r) === 2 || Math.abs(c) === 2 || (r === 0 && c === 0)) {
            matrix[align + r][align + c] = 1;
          } else {
            matrix[align + r][align + c] = 0;
          }
        }
      }
    }

    // 3. Timing patterns
    for (let i = 8; i < size - 8; i++) {
      matrix[6][i] = i % 2 === 0 ? 1 : 0;
      matrix[i][6] = i % 2 === 0 ? 1 : 0;
    }

    // 4. Dark module
    matrix[size - 8][8] = 1;

    // 5. Hash & pack payload data
    let hash = 0;
    for (let i = 0; i < text.length; i++) {
      hash = (hash * 31 + text.charCodeAt(i)) & 0xFFFFFFFF;
    }

    let byteIdx = 0;
    let bitIdx = 7;
    for (let c = size - 1; c > 0; c -= 2) {
      if (c === 6) c--; // skip vertical timing line
      for (let r = 0; r < size; r++) {
        for (let step = 0; step < 2; step++) {
          const col = c - step;
          const row = (Math.floor(c / 2) % 2 === 0) ? (size - 1 - r) : r;
          if (matrix[row][col] === 0) {
            // Check if within finder/reserved zones
            const inFinder1 = (row <= 8 && col <= 8);
            const inFinder2 = (row <= 8 && col >= size - 9);
            const inFinder3 = (row >= size - 9 && col <= 8);
            if (!inFinder1 && !inFinder2 && !inFinder3) {
              const charVal = text.charCodeAt(byteIdx % text.length);
              const bit = (charVal >> bitIdx) & 1;
              // Mask pattern: (row + col) % 2 === 0
              const mask = (row + col) % 2 === 0 ? 1 : 0;
              matrix[row][col] = bit ^ mask;
              
              bitIdx--;
              if (bitIdx < 0) {
                bitIdx = 7;
                byteIdx++;
              }
            }
          }
        }
      }
    }

    return matrix;
  }

  return QRCode;
}));
